node -e "
const Database = require('/workspace/node_modules/better-sqlite3');
const db = new Database('/workspace/world.db');

// Current state
const cart = db.prepare('SELECT * FROM carts WHERE cart_id = ?').get('CART-user_d3d5d0c8');
const user = db.prepare('SELECT loyalty_points, loyalty_tier FROM users WHERE user_id = ?').get('user_d3d5d0c8');

console.log('Cart subtotal:', cart.subtotal);
console.log('Cart shipping:', cart.shipping_cost);
console.log('Cart total (before points):', cart.total);
console.log('User loyalty points:', user.loyalty_points);

// Points conversion: 100 points = \$1
const pointsAvailable = user.loyalty_points;  // 5623
const maxDiscountValue = Math.floor(pointsAvailable / 100); // \$56
const cartSubtotal = cart.subtotal; // \$49 (apply against subtotal, not shipping)

// Apply points up to the subtotal amount
const loyaltyDiscount = Math.min(maxDiscountValue, cartSubtotal); // \$49
const pointsToRedeem = loyaltyDiscount * 100; // 4900

console.log('\n--- Calculation ---');
console.log('Points value available: \$' + maxDiscountValue);
console.log('Loyalty discount to apply: \$' + loyaltyDiscount);
console.log('Points to redeem:', pointsToRedeem);
console.log('Remaining points:', pointsAvailable - pointsToRedeem);

const newTotal = cart.subtotal - loyaltyDiscount + cart.shipping_cost;
console.log('New cart total: \$' + newTotal);

// Apply: update cart
db.prepare('UPDATE carts SET loyalty_discount = ?, loyalty_points_redeemed = ?, total = ? WHERE cart_id = ?')
  .run(loyaltyDiscount, pointsToRedeem, newTotal, 'CART-user_d3d5d0c8');

// Deduct points from user
db.prepare('UPDATE users SET loyalty_points = loyalty_points - ? WHERE user_id = ?')
  .run(pointsToRedeem, 'user_d3d5d0c8');

// Verify
const updatedCart = db.prepare('SELECT * FROM carts WHERE cart_id = ?').get('CART-user_d3d5d0c8');
const updatedUser = db.prepare('SELECT loyalty_points FROM users WHERE user_id = ?').get('user_d3d5d0c8');

console.log('\n=== UPDATED CART ===');
console.log(JSON.stringify(updatedCart, null, 2));
console.log('\n=== UPDATED USER POINTS ===');
console.log('Remaining loyalty points:', updatedUser.loyalty_points);
"

