node -e "
const Database = require('/workspace/node_modules/better-sqlite3');
const db = new Database('/workspace/world.db');

// Current state before update
const cartBefore = db.prepare('SELECT * FROM carts WHERE cart_id = ?').get('CART-user_d3d5d0c8');
const itemBefore = db.prepare('SELECT * FROM cart_items WHERE cart_item_id = ?').get('CI-0023');
const product = db.prepare('SELECT price FROM products WHERE product_id = ?').get('PROD-F9994E');

console.log('=== BEFORE ===');
console.log('Item qty:', itemBefore.quantity);
console.log('Product unit price:', product.price);
console.log('Cart subtotal:', cartBefore.subtotal);
console.log('Loyalty discount:', cartBefore.loyalty_discount);
console.log('Loyalty points redeemed:', cartBefore.loyalty_points_redeemed);
console.log('Shipping:', cartBefore.shipping_cost);
console.log('Total:', cartBefore.total);

// Update quantity to 2
db.prepare('UPDATE cart_items SET quantity = 2 WHERE cart_item_id = ?').run('CI-0023');

// Recalculate subtotal: 2 x \$49 = \$98
const newSubtotal = product.price * 2;
// Keep existing loyalty discount as-is (\$49 / 4900 pts already redeemed)
const loyaltyDiscount = cartBefore.loyalty_discount;
const shippingCost = cartBefore.shipping_cost;
const newTotal = newSubtotal - loyaltyDiscount - cartBefore.discount_amount + cartBefore.gift_wrap_fee + shippingCost;

// Update cart totals
db.prepare('UPDATE carts SET subtotal = ?, total = ? WHERE cart_id = ?')
  .run(newSubtotal, newTotal, 'CART-user_d3d5d0c8');

// Verify
const cartAfter = db.prepare('SELECT * FROM carts WHERE cart_id = ?').get('CART-user_d3d5d0c8');
const itemAfter = db.prepare('SELECT * FROM cart_items WHERE cart_item_id = ?').get('CI-0023');
const user = db.prepare('SELECT loyalty_points FROM users WHERE user_id = ?').get('user_d3d5d0c8');

console.log('\n=== AFTER ===');
console.log(JSON.stringify(cartAfter, null, 2));
console.log('Item quantity:', itemAfter.quantity);
console.log('Remaining loyalty points:', user.loyalty_points);
"
